sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader backdrop;
uniform float threshold;
uniform float feather;
uniform float density;
uniform float offset;
uniform float mode;
uniform float sampling;
half4 main(float2 coord) {
    half4 col = image.eval(coord);
    if (col.a < 1e-3) return half4(0);
    float2 p = coord;
    if (sampling > 0.5) p = floor(coord / 2.0) * 2.0 + 1.0;
    half4 bg = backdrop.eval(p);
    float diff;
    if (bg.a < 1e-3) {
        diff = 1.0;
    } else {
        float3 rgb = float3(col.rgb / col.a);
        float3 bgrgb = float3(bg.rgb / bg.a);
        diff = clamp(length(rgb - bgrgb) / 1.7320508, 0.0, 1.0);
    }
    float t = clamp(threshold + offset, 0.0, 1.0);
    float matte = smoothstep(t, t + max(feather, 0.001), diff);
    matte = pow(matte, max(1.0 - density, 0.001));
    if (mode > 0.5) {
        return half4(half3(diff) * col.a, col.a);
    }
    return col * half(matte);
}
